// Package graph is the demo store's GraphQL API: the "internal system" the
// example agents are connected to. The executable schema is generated by
// gqlgen from schema.graphqls.
package graph

import (
	"crypto/subtle"
	"errors"
	"net/http"
	"strings"

	"github.com/99designs/gqlgen/graphql/handler"
	"github.com/99designs/gqlgen/graphql/handler/extension"
	"github.com/99designs/gqlgen/graphql/handler/transport"

	"github.com/wojtekmanke/roster/internal/shop"
)

// Resolver holds the resolvers' dependencies.
type Resolver struct {
	Shop *shop.Shop
}

// NewHandler serves the shop API. When token is set, callers must present it
// as a bearer token, which is how the example agents show a tool carrying a
// credential from the environment.
func NewHandler(s *shop.Shop, token string) http.Handler {
	srv := handler.New(NewExecutableSchema(Config{Resolvers: &Resolver{Shop: s}}))
	srv.AddTransport(transport.Options{})
	// GET is accepted for queries because common clients send short queries
	// that way by default. Mutations over GET are refused by the transport.
	srv.AddTransport(transport.GET{})
	srv.AddTransport(transport.POST{})
	srv.Use(extension.Introspection{})
	if token == "" {
		return srv
	}
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		got := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
		if subtle.ConstantTimeCompare([]byte(got), []byte(token)) != 1 {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		srv.ServeHTTP(w, r)
	})
}

// optional maps "not found" to null for nullable lookups.
func optional[T any](v *T, err error) (*T, error) {
	if errors.Is(err, shop.ErrNotFound) {
		return nil, nil
	}
	return v, err
}

// found turns "not found" into an error a caller can act on.
func found[T any](v *T, err error) (*T, error) {
	if errors.Is(err, shop.ErrNotFound) {
		return nil, errors.New("no such record")
	}
	return v, err
}
